@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;700&display=swap');
:root{--ink:#07111f;--muted:#89a2b9;--cyan:#65e8ff;--pink:#ff4d9d;--gold:#ffcf5a;--panel:rgba(12,28,48,.92)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);font-family:'DM Sans',sans-serif;color:#f5fbff;touch-action:none}button{font:inherit;color:inherit;cursor:pointer;border:0}#app{position:relative;width:100%;height:100%;overflow:hidden;background:#07111f}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.screen{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;overflow:auto;padding:7vh 18px 30px}.menu-backdrop{position:absolute;inset:0;overflow:hidden;pointer-events:none;background:radial-gradient(circle at 50% 30%,#18385b 0,#0d213b 38%,#07111f 80%)}.orb{position:absolute;border-radius:50%;filter:blur(2px);opacity:.28}.orb-a{width:55vw;height:55vw;right:-20vw;top:-15vw;background:#c2368b;box-shadow:0 0 100px #c2368b}.orb-b{width:40vw;height:40vw;left:-18vw;bottom:5vh;background:#147fbd;box-shadow:0 0 120px #147fbd}.grid-lines{position:absolute;inset:40% -20% -20%;opacity:.18;background:linear-gradient(115deg,transparent 49.5%,#65e8ff 50%,transparent 50.5%),linear-gradient(65deg,transparent 49.5%,#65e8ff 50%,transparent 50.5%);background-size:80px 80px;transform:perspective(220px) rotateX(44deg);mask-image:linear-gradient(transparent,#000)}.brand{position:relative;text-align:center;margin-bottom:4vh;filter:drop-shadow(0 8px 20px #0008)}.brand-kicker,.eyebrow{letter-spacing:.25em;font-size:10px;font-weight:700;color:var(--cyan)}h1,h2,p{margin:0}.brand h1{font-family:'Barlow Condensed';font-size:clamp(54px,15vw,94px);line-height:.83;letter-spacing:-.03em;font-weight:900;margin:10px 0}.brand h1 span{color:var(--pink)}.brand p{font-size:10px;letter-spacing:.5em;color:#bad3e6}.panel{position:relative;width:min(510px,100%);background:linear-gradient(145deg,#102a46eF,#091a2eeF);border:1px solid #6de6ff28;border-radius:24px;padding:22px;box-shadow:0 20px 70px #0008;backdrop-filter:blur(18px)}.menu-panel{padding:18px}.profile-row{display:flex;align-items:center;gap:12px;padding:4px 4px 18px}.profile-row b{display:block;font-size:14px}.profile-row small{color:var(--muted);font-size:11px}.avatar{display:grid;place-items:center;width:44px;height:44px;border-radius:14px;background:linear-gradient(135deg,#ff9b4a,#ff3c9b);font-family:'Barlow Condensed';font-size:26px;font-weight:800}.coin-balance{margin-left:auto;color:var(--gold);font-size:14px}.primary-btn,.secondary-btn,.text-btn,.back-btn{transition:.18s transform,.18s filter}.primary-btn:active,.secondary-btn:active,.text-btn:active{transform:scale(.97)}.primary-btn{width:100%;padding:17px;border-radius:13px;background:linear-gradient(100deg,#ff477e,#ff785c);font-family:'Barlow Condensed';font-size:21px;font-weight:800;letter-spacing:.1em;box-shadow:0 10px 25px #f54b6b55}.primary-btn span{margin-right:10px}.quick-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:10px}.secondary-btn{padding:13px 8px;border-radius:11px;background:#1a3b59;border:1px solid #7ae9ff25;font-size:11px;font-weight:700;letter-spacing:.08em}.secondary-btn:hover,.text-btn:hover{filter:brightness(1.25)}.menu-footer{display:flex;justify-content:space-between;margin-top:8px}.text-btn{background:transparent;padding:10px;color:#a6bfd1;font-size:11px;letter-spacing:.08em}.hidden{display:none!important}.select-panel{min-height:360px}.back-btn{background:none;color:#a9c2d5;font-size:11px;letter-spacing:.1em;padding:0 0 18px}.panel-heading h2{font-family:'Barlow Condensed';font-size:36px;line-height:1;margin:7px 0}.panel-heading p{color:var(--muted);font-size:12px;margin-bottom:19px}.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.card{position:relative;text-align:left;min-height:112px;padding:13px;border-radius:15px;overflow:hidden;background:linear-gradient(135deg,var(--card),#132741);border:1px solid #ffffff12}.card.selected{border-color:var(--cyan);box-shadow:0 0 0 1px var(--cyan),0 8px 25px #65e8ff22}.card .portrait{font-family:'Barlow Condensed';font-weight:900;font-size:40px;line-height:1;color:#ffffffbb;text-shadow:3px 4px 0 #0005}.card b{display:block;font-size:13px;margin-top:8px}.card small{color:#c6d6e0;font-size:9px}.card .lock{position:absolute;right:11px;top:11px;font-size:14px}.swipe-hint{text-align:center;color:#7190a7;font-size:10px;margin-top:17px}.upgrade-row{display:flex;align-items:center;gap:12px;padding:15px 0;border-top:1px solid #ffffff10}.upgrade-row:first-child{border-top:0}.upgrade-icon{font-size:24px;color:var(--cyan)}.upgrade-row strong{display:block;font-size:13px}.upgrade-row small{color:var(--muted);font-size:10px}.upgrade-row button{margin-left:auto;background:#254b67;border-radius:8px;padding:9px 12px;color:var(--gold);font-weight:700;font-size:11px}.hud{position:absolute;inset:0;pointer-events:none}.hud button,.hud .ability-btn,.hud .ultimate-btn{pointer-events:auto}.hud-top{display:flex;gap:9px;padding:calc(env(safe-area-inset-top) + 15px) 15px 0}.stat-chip{background:#071828bd;border:1px solid #7cdcf629;border-radius:11px;padding:7px 11px;min-width:76px}.label{display:block;font-size:8px;color:#88aabe;letter-spacing:.12em}.stat-chip strong{font-family:'Barlow Condensed';font-size:20px}.pause-btn{margin-left:auto;width:40px;height:40px;border-radius:12px;background:#112c45dd;border:1px solid #ffffff16;font-size:18px}.hud-bottom{position:absolute;bottom:calc(env(safe-area-inset-bottom) + 15px);left:15px;right:15px;display:flex;gap:8px;align-items:end}.resource{font-family:'Barlow Condensed';font-size:22px;color:var(--gold);background:#071828c9;padding:9px 11px;border-radius:11px}.health{font-size:14px;letter-spacing:2px;color:#ff668a;background:#071828c9;padding:12px 8px;border-radius:11px}.energy-wrap{flex:1;align-self:center;max-width:180px}.energy-label{font-size:9px;letter-spacing:.1em;color:#a5bdd0;margin-bottom:5px}.energy-label b{color:var(--cyan);float:right}.energy-bar,.boss-bar{height:8px;background:#142b41;border-radius:9px;overflow:hidden}.energy-bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#35bbff,#ad77ff);box-shadow:0 0 12px #65e8ff}.ability-btn,.ultimate-btn{width:70px;height:70px;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;background:linear-gradient(145deg,#263f78,#37234f);border:2px solid #966cff;color:#fff;box-shadow:0 0 20px #7762ff45}.ability-btn span,.ultimate-btn span{font-size:23px}.ability-btn b,.ultimate-btn b{font-size:8px;letter-spacing:.06em}.ability-btn small{font-size:8px;color:#a8cdf1}.ultimate-btn{border-color:var(--gold);background:linear-gradient(145deg,#8b5520,#4e2847);color:var(--gold);opacity:.45}.ultimate-btn:not(:disabled){opacity:1;animation:pulse 1.2s infinite}.toast{position:absolute;top:23%;left:50%;transform:translateX(-50%);padding:10px 16px;background:#061727ee;border:1px solid #65e8ff66;border-radius:20px;color:var(--cyan);font-size:12px;font-weight:700;opacity:0;transition:.3s}.toast.show{opacity:1}.boss-hud{position:absolute;top:17%;left:15%;right:15%;text-align:center}.boss-name{font-family:'Barlow Condensed';letter-spacing:.15em;font-size:18px;color:#ff799d;margin-bottom:7px}.boss-bar i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#ff3c67,#ffca5b)}.boss-help{font-size:9px;color:#b9c9d6;margin-top:7px}.overlay{position:absolute;inset:0;display:grid;place-items:center;padding:20px;background:#040d18aa;backdrop-filter:blur(9px)}.modal{width:min(380px,100%);padding:29px 23px;text-align:center;border-radius:24px;background:linear-gradient(145deg,#122f4b,#091a2c);border:1px solid #65e8ff40;box-shadow:0 25px 80px #000b}.modal h2{font-family:'Barlow Condensed';font-size:38px;margin:9px 0 22px}.modal .secondary-btn,.modal .text-btn{margin-top:9px}.wide{width:100%}.danger{color:#ff7f9d}.results{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:20px}.results div{background:#0b2137;border-radius:11px;padding:10px}.results small{display:block;font-size:8px;color:#8da7bb}.results b{font-family:'Barlow Condensed';font-size:24px;color:var(--cyan)}.modal p{font-size:12px;color:#9bb2c4;margin-bottom:18px}.boss-modal{border-color:#ff678a66}
@keyframes pulse{50%{transform:scale(1.06);box-shadow:0 0 28px #ffcf5a99}}@media(min-width:700px){.screen{padding-top:8vh}.brand h1{font-size:88px}.panel{width:530px}.hud-bottom{left:28px;right:28px}.cards{grid-template-columns:repeat(3,1fr)}}

(() => {
'use strict';
const canvas=document.getElementById('gameCanvas'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id); const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const characters=[
 {id:'naruto',name:'Naruto Uzumaki',universe:'Naruto',tag:'Hidden Leaf',color:'#f59b32',accent:'#55d8ff',initial:'N',ability:'Rasengan Dash',desc:'Clears the path ahead',speed:1},
 {id:'sasuke',name:'Adult Sasuke',universe:'Naruto',tag:'Shinobi War',color:'#845dff',accent:'#dc5cff',initial:'S',ability:'Susanoo Shield',desc:'Blocks one hit',speed:1.04},
 {id:'kurama',name:'Kurama',universe:'Naruto',tag:'Nine-Tails',color:'#ec473b',accent:'#ffcf5a',initial:'K',ability:'Chakra Boost',desc:'Speed burst',speed:1.1},
 {id:'yuji',name:'Yuji Itadori',universe:'Jujutsu',tag:'Cursed City',color:'#ec5275',accent:'#ffb543',initial:'Y',ability:'Black Flash',desc:'Smashes hazards',speed:1.02},
 {id:'sukuna',name:'Ryomen Sukuna',universe:'Jujutsu',tag:'Dark Battlefield',color:'#bf405b',accent:'#ff8a4d',initial:'R',ability:'Cleave',desc:'Cuts through danger',speed:1.06},
 {id:'gojo',name:'Satoru Gojo',universe:'Jujutsu',tag:'Shibuya Sector',color:'#5c8cff',accent:'#c9f3ff',initial:'G',ability:'Infinity',desc:'Untouchable for 4s',speed:1.03},
 {id:'tanjiro',name:'Tanjiro Kamado',universe:'Demon Slayer',tag:'Dark Forest',color:'#328f83',accent:'#87dcf2',initial:'T',ability:'Water Breathing',desc:'A flowing speed dash',speed:1},
 {id:'nezuko',name:'Nezuko Kamado',universe:'Demon Slayer',tag:'Demon Castle',color:'#d66da1',accent:'#ffb4db',initial:'N',ability:'Demon Rage',desc:'Recovers one heart',speed:1.05},
 {id:'inosuke',name:'Inosuke Hashibira',universe:'Demon Slayer',tag:'Mountain Pass',color:'#5791a1',accent:'#e1fdff',initial:'I',ability:'Beast Rush',desc:'Leaps over hazards',speed:1.08},
 {id:'zenitsu',name:'Zenitsu Agatsuma',universe:'Demon Slayer',tag:'Village Night',color:'#e4ae35',accent:'#fff2a1',initial:'Z',ability:'Thunderclap',desc:'Lightning speed boost',speed:1.12},
 {id:'saitama',name:'Saitama',universe:'One Punch',tag:'Destroyed City',color:'#eacb3e',accent:'#e94654',initial:'S',ability:'One Punch',desc:'Obliterates all hazards',speed:1.08},
 {id:'genos',name:'Genos',universe:'One Punch',tag:'Futuristic City',color:'#e98345',accent:'#66eaff',initial:'G',ability:'Incineration',desc:'Burns hazards ahead',speed:1.06},
 {id:'tatsumaki',name:'Tatsumaki',universe:'One Punch',tag:'Alien Battlefield',color:'#55c78d',accent:'#c1ff7f',initial:'T',ability:'Psychic Storm',desc:'Suspends danger',speed:1.1}
];
const universes={Naruto:{sky:'#102f55',ground:'#173f50',glow:'#ff754d',enemy:'Nine-Tails Pursuer',boss:'The Tailed Colossus',obstacles:['fallen tree','chakra wall','war debris']},Jujutsu:{sky:'#1c2045',ground:'#29304c',glow:'#a65cff',enemy:'Special Grade Curse',boss:'The Hollow Curse',obstacles:['cursed barrier','ruined car','energy spike']},'Demon Slayer':{sky:'#162e37',ground:'#244b45',glow:'#54d7ca',enemy:'Upper Moon Demon',boss:'The Castle Fiend',obstacles:['fallen cedar','stone shrine','demon web']},'One Punch':{sky:'#30304e',ground:'#3e4d59',glow:'#ffbf4d',enemy:'Dragon Threat',boss:'The Alien Tyrant',obstacles:['concrete block','alien wreckage','monster spike']}};
let save=JSON.parse(localStorage.getItem('animeRushSave')||'null')||{coins:0,best:0,selected:'naruto',speed:0,shield:0,ability:0};
let selected=characters.find(c=>c.id===save.selected)||characters[0], universe=universes[selected.universe];
let W=0,H=0,dpr=1,state='menu',last=0,raf=0,run=null,particles=[];
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)} addEventListener('resize',resize);resize();
function persist(){save.selected=selected.id;localStorage.setItem('animeRushSave',JSON.stringify(save))}
function show(id,yes=true){$(id).classList.toggle('hidden',!yes)}
function menu(){state='menu';show('screen',true);show('menuPanel',true);show('selectPanel',false);show('upgradePanel',false);show('hud',false);show('pauseOverlay',false);show('gameOverOverlay',false);show('bossOverlay',false);updateMenu();}
function updateMenu(){universe=universes[selected.universe];$('menuCharacter').textContent=selected.name;$('menuUniverse').textContent=`${selected.tag} • ${selected.universe}`;$('menuCoins').textContent=save.coins;$('menuAvatar').textContent=selected.initial;$('menuAvatar').style.background=`linear-gradient(135deg,${selected.color},${selected.accent})`}
function cards(type){let list=type==='universe'?Object.keys(universes):characters; $('selectEyebrow').textContent=type==='universe'?'WORLDS':'ROSTER';$('selectTitle').textContent=type==='universe'?'Choose your universe':'Choose your runner';$('selectHint').textContent=type==='universe'?'Every world changes the chase, hazards and atmosphere.':'Every fighter brings a different edge.';$('cards').innerHTML='';list.forEach(item=>{let isU=type==='universe', active=isU?selected.universe===item:item.id===selected.id;let d=isU?universes[item]:item;let el=document.createElement('button');el.className='card'+(active?' selected':'');el.style.setProperty('--card',isU?d.glow:item.color);el.innerHTML=isU?`<div class="portrait">${item==='Demon Slayer'?'刃':item==='One Punch'?'拳':item==='Jujutsu'?'呪':'忍'}</div><b>${item}</b><small>${d.enemy} • ${d.obstacles[0]}</small>`:`<div class="portrait">${item.initial}</div><b>${item.name}</b><small>${item.universe} • ${item.ability}</small>${item.id!=='naruto'&&item.id!=='gojo'&&item.id!=='tanjiro'&&item.id!=='saitama'?'<span class="lock">✦</span>':''}`;el.onclick=()=>{if(isU){let c=characters.find(x=>x.universe===item)||selected;universe=universes[item];selected={...c};save.selected=selected.id}else selected=item;persist();cards(type);updateMenu();toast(`${isU?item:selected.name} selected`)};$('cards').appendChild(el)})}
function openSelect(type){show('menuPanel',false);show('upgradePanel',false);show('selectPanel',true);cards(type)}
function openUpgrades(){show('menuPanel',false);show('selectPanel',false);show('upgradePanel',true);renderUpgrades()}
function renderUpgrades(){let rows=[['⚡','Runner speed','Faster base movement','speed'],['◈','Starting shield','Begin with more protection','shield'],['✦','Ability mastery','Shorter cooldowns','ability']];$('upgradeList').innerHTML=rows.map(([icon,name,desc,key])=>{let lvl=save[key]||0,cost=100+lvl*125;return `<div class="upgrade-row"><span class="upgrade-icon">${icon}</span><div><strong>${name} · LV ${lvl}</strong><small>${desc}</small></div><button data-key="${key}" data-cost="${cost}">◈ ${cost}</button></div>`}).join('');document.querySelectorAll('.upgrade-row button').forEach(b=>b.onclick=()=>{let k=b.dataset.key,c=+b.dataset.cost;if(save.coins>=c){save.coins-=c;save[k]++;persist();renderUpgrades();updateMenu();toast('Upgrade installed')}else toast(`Need ${c-save.coins} more coins`)})}
function toast(msg){let t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),1400)}
function newRun(){cancelAnimationFrame(raf);state='playing';show('screen',false);show('hud',true);show('gameOverOverlay',false);show('pauseOverlay',false);show('bossOverlay',false);run={time:0,distance:0,score:0,coins:0,energy:0,health:3,lane:1,x:0,jumpY:0,vy:0,slide:0,hitCooldown:0,abilityCd:0,abilityTime:0,ultimate:0,ultimateTime:0,spawn:1.2,collectSpawn:.6,objects:[],chaser:0.18,avoided:0,bosses:0,boss:null,nextBoss:2000,shake:0};$('abilityLabel').textContent=selected.ability.split(' ')[0].toUpperCase();$('abilityIcon').textContent=selected.initial;$('energyFill').style.width='0%';$('energyText').textContent='0%';$('bossHud').classList.add('hidden');updateHud();last=performance.now();raf=requestAnimationFrame(loop);toast(`${selected.name} enters ${selected.tag}`)}
function updateHud(){if(!run)return;$('distance').textContent=Math.floor(run.distance)+'m';$('score').textContent=Math.floor(run.score);$('runCoins').textContent=run.coins;$('healthHearts').textContent='♥'.repeat(run.health)+'♡'.repeat(3-run.health);$('energyFill').style.width=run.energy+'%';$('energyText').textContent=Math.floor(run.energy)+'%';$('abilityCooldown').textContent=run.abilityCd>0?run.abilityCd.toFixed(1)+'s':'READY';$('ultimateBtn').disabled=run.energy<100||run.ultimateTime>0}
function spawn(type,lane,z){run.objects.push({type,lane,z,hit:false,spin:Math.random()*6.2,phase:Math.random()*6.2})}
function spawnPattern(){let lane=Math.floor(Math.random()*3),r=Math.random();if(r<.52)spawn('obstacle',lane,1.08);else if(r<.72)spawn('overhead',lane,1.08);else if(r<.86)spawn('coin',lane,1.08);else spawn('energy',lane,1.08);if(r>.72&&r<.9)spawn('coin',(lane+1)%3,1.2)}
function activateAbility(){if(state!=='playing'||run.abilityCd>0||run.boss&&run.boss.intro)return;if(selected.id==='nezuko'&&run.health<3)run.health++;if(selected.id==='gojo'||selected.id==='sasuke')run.abilityTime=4;else if(selected.id==='kurama'||selected.id==='zenitsu'||selected.id==='tanjiro')run.abilityTime=3.5;else{run.objects.forEach(o=>{if(o.type==='obstacle'||o.type==='overhead')o.hit=true});run.abilityTime=1.5}run.abilityCd=Math.max(2.8,5.2-(save.ability||0)*.35);run.shake=.18;burst(W*.5,H*.55,selected.accent,18);toast(selected.ability+'!');updateHud()}
function activateUltimate(){if(state!=='playing'||run.energy<100||run.ultimateTime>0)return;run.energy=0;run.ultimateTime=7;run.ultimate=1;run.objects.forEach(o=>{if(o.type==='obstacle'||o.type==='overhead')o.hit=true});burst(W/2,H*.5,universe.glow,45);toast('ULTIMATE MODE — UNSTOPPABLE');updateHud()}
function jump(){if(state==='playing'&&run.jumpY===0&&run.slide<=0){run.vy=1.55;burst(playerScreen().x,playerScreen().y+25,'#b9f4ff',8)}}function slide(){if(state==='playing'&&run.jumpY===0){run.slide=.72}}
function lane(dir){if(state==='playing')run.lane=clamp(run.lane+dir,0,2)}
function playerScreen(){let horizon=H*.37,ground=H*.79;return{x:W/2+(run?run.x:0),y:ground-(run?run.jumpY*H*.15:0)}}
function hitObstacle(o){if(run.hitCooldown>0||run.ultimateTime>0||run.abilityTime>0)return;run.hitCooldown=1.1;run.health--;run.chaser=clamp(run.chaser+.18,0,1);run.shake=.4;burst(playerScreen().x,playerScreen().y,'#ff577d',24);toast('IMPACT! KEEP MOVING');if(run.health<=0||run.chaser>=.98)endRun()}
function collect(o){o.hit=true;if(o.type==='coin'){run.coins++;run.score+=75;burst(o.screenX,o.screenY,'#ffcf5a',8)}else{run.energy=clamp(run.energy+14,0,100);run.score+=120;burst(o.screenX,o.screenY,'#65e8ff',10)}updateHud()}
function startBoss(){state='bossIntro';run.boss={hp:100,time:24,intro:true,attack:2};$('bossIntro').textContent=universe.boss+' approaches.';show('bossOverlay',true);$('bossName').textContent=universe.boss.toUpperCase();$('bossFill').style.width='100%'}
function enterBoss(){state='boss';run.boss.intro=false;show('bossOverlay',false);show('bossHud',true);toast('BOSS BATTLE — USE YOUR ABILITY');last=performance.now();raf=requestAnimationFrame(loop)}
function bossAbility(){if(state==='boss'){if(run.abilityCd<=0){run.boss.hp-=selected.id==='saitama'?45:28;run.abilityCd=2.2;run.boss.attack=2.5;burst(W/2,H*.47,selected.accent,28);toast('DIRECT HIT!');$('bossFill').style.width=clamp(run.boss.hp,0,100)+'%';if(run.boss.hp<=0){run.bosses++;run.score+=1500;run.coins+=25;run.distance+=80;state='playing';show('bossHud',false);toast('BOSS DEFEATED +25 COINS')}}return}activateAbility()}
function update(dt){run.time+=dt;run.hitCooldown=Math.max(0,run.hitCooldown-dt);run.abilityCd=Math.max(0,run.abilityCd-dt);run.slide=Math.max(0,run.slide-dt);run.abilityTime=Math.max(0,run.abilityTime-dt);if(run.ultimateTime>0){run.ultimateTime-=dt;if(run.ultimateTime<=0)run.ultimate=0}let speed=(.29+Math.min(run.distance/9000,.18))*(selected.speed||1)*(1+(save.speed||0)*.045);if(run.ultimateTime>0||run.abilityTime>0&&['kurama','zenitsu','tanjiro'].includes(selected.id))speed*=1.35;run.distance+=speed*dt*100;run.score+=speed*dt*55;run.x+=(run.lane-1)*W*.19-run.x; // smooth lane interpolation
if(run.jumpY>0||run.vy>0){run.jumpY+=run.vy*dt;run.vy-=3.8*dt;if(run.jumpY<=0){run.jumpY=0;run.vy=0;burst(playerScreen().x,playerScreen().y+30,'#65e8ff',6)}}
if(run.hitCooldown<=0&&run.health<3&&Math.random()<dt*.018)run.health++;
run.spawn-=dt;if(run.spawn<=0){spawnPattern();run.spawn=Math.max(.48,1.12-run.distance/9000)+Math.random()*.35}
run.collectSpawn-=dt;if(run.collectSpawn<=0){let l=Math.floor(Math.random()*3);spawn(Math.random()<.25?'energy':'coin',l,1.12);run.collectSpawn=.65+Math.random()*.6}
