await (async page => { await page.locator('#retryBtn').click(); const canvas=page.locator('#gameCanvas'); const counts=()=>canvas.evaluate(c=>{const d=c.getContext('2d').getImageData(0,0,c.width,c.height).data,r=[0,0,0];for(let y=Math.floor(c.height*.72);y<Math.floor(c.height*.82);y++)for(let x=0;x<c.width;x++){const i=(y*c.width+x)*4;if(d[i]>65&&d[i+2]>130&&d[i+1]>90&&d[i+1]<190)r[Math.min(2,Math.floor(x/(c.width/3)))]++}return r}); const swipe=async(x1,y1,x2,y2)=>canvas.evaluate((c,v)=>{const a=(x,y)=>new Touch({identifier:1,target:c,clientX:x,clientY:y});c.dispatchEvent(new TouchEvent('touchstart',{changedTouches:[a(v[0],v[1])],bubbles:true}));c.dispatchEvent(new TouchEvent('touchend',{changedTouches:[a(v[2],v[3])],bubbles:true}));},[x1,y1,x2,y2]); await page.waitForTimeout(100);let before=await counts();await swipe(190,400,80,400);await page.waitForTimeout(500);let left=await counts();await swipe(190,400,190,300);await page.waitForTimeout(300);let jump=await counts();await swipe(190,300,190,410);await page.waitForTimeout(300);let slide=await counts();return{before,left,jump,slide,distance:await page.locator('#distance').textContent(),gameOver:await page.locator('#gameOverOverlay').isVisible()}; })(page);
